--
-- Name: academic_goals; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.academic_goals (
    id uuid NOT NULL,
    student_id uuid NOT NULL,
    target_exam character varying(100) NOT NULL,
    exam_date date NOT NULL,
    available_daily_minutes integer NOT NULL,
    status character varying(9) DEFAULT 'ACTIVE'::character varying NOT NULL,
    target_university character varying(200),
    target_major character varying(200),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_academic_goals_academic_goal_status CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'COMPLETED'::character varying, 'ABANDONED'::character varying, 'ARCHIVED'::character varying])::text[]))),
    CONSTRAINT ck_academic_goals_daily_minutes CHECK (((available_daily_minutes > 0) AND (available_daily_minutes <= 1440)))
);


ALTER TABLE public.academic_goals OWNER TO postgres;

--
-- Name: adaptive_repair_decisions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.adaptive_repair_decisions (
    id uuid NOT NULL,
    adaptive_repair_session_id uuid NOT NULL,
    adaptive_repair_item_id uuid NOT NULL,
    decision_index integer NOT NULL,
    phase_before character varying(15) NOT NULL,
    phase_after character varying(15) NOT NULL,
    difficulty_before double precision NOT NULL,
    difficulty_after double precision NOT NULL,
    reason_code character varying(31) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_adaptive_repair_decisions_ck_adaptive_repair_decisio_5e54 CHECK ((decision_index > 0)),
    CONSTRAINT ck_adaptive_repair_decisions_ck_adaptive_repair_decisio_8138 CHECK (((difficulty_before >= (0)::double precision) AND (difficulty_before <= (1)::double precision))),
    CONSTRAINT ck_adaptive_repair_decisions_ck_adaptive_repair_decisio_9191 CHECK (((difficulty_after >= (0)::double precision) AND (difficulty_after <= (1)::double precision)))
);


ALTER TABLE public.adaptive_repair_decisions OWNER TO postgres;

--
-- Name: adaptive_repair_items; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.adaptive_repair_items (
    id uuid NOT NULL,
    adaptive_repair_session_id uuid NOT NULL,
    question_id uuid NOT NULL,
    order_index integer NOT NULL,
    role character varying(13) NOT NULL,
    desired_difficulty double precision NOT NULL,
    selection_score double precision,
    selection_reason character varying(100) NOT NULL,
    attempt_id uuid,
    difficulty_before double precision NOT NULL,
    difficulty_after double precision,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    answered_at timestamp with time zone,
    CONSTRAINT ck_adaptive_repair_items_ck_adaptive_repair_items_desir_484b CHECK (((desired_difficulty >= (0)::double precision) AND (desired_difficulty <= (1)::double precision))),
    CONSTRAINT ck_adaptive_repair_items_ck_adaptive_repair_items_diffi_3b18 CHECK (((difficulty_before >= (0)::double precision) AND (difficulty_before <= (1)::double precision))),
    CONSTRAINT ck_adaptive_repair_items_ck_adaptive_repair_items_diffi_9a5b CHECK (((difficulty_after IS NULL) OR ((difficulty_after >= (0)::double precision) AND (difficulty_after <= (1)::double precision)))),
    CONSTRAINT ck_adaptive_repair_items_ck_adaptive_repair_items_order_5e50 CHECK ((order_index > 0))
);


ALTER TABLE public.adaptive_repair_items OWNER TO postgres;

--
-- Name: adaptive_repair_sessions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.adaptive_repair_sessions (
    id uuid NOT NULL,
    practice_session_id uuid NOT NULL,
    student_id uuid NOT NULL,
    subject_id uuid NOT NULL,
    diagnosis_id uuid NOT NULL,
    verification_id uuid NOT NULL,
    verification_target_id uuid NOT NULL,
    target_type character varying(13) NOT NULL,
    target_concept_id uuid,
    target_problem_type_id uuid,
    misconception_definition_id uuid,
    target_name character varying(255),
    target_code character varying(100),
    status character varying(9) NOT NULL,
    phase character varying(15) NOT NULL,
    outcome character varying(19) NOT NULL,
    initial_difficulty double precision NOT NULL,
    current_difficulty double precision NOT NULL,
    target_exit_difficulty double precision NOT NULL,
    verification_average_score double precision,
    attempted_count integer DEFAULT 0 NOT NULL,
    correct_count integer DEFAULT 0 NOT NULL,
    consecutive_correct integer DEFAULT 0 NOT NULL,
    consecutive_wrong integer DEFAULT 0 NOT NULL,
    max_questions integer DEFAULT 8 NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    repair_cycle_index integer DEFAULT 1 NOT NULL,
    previous_adaptive_repair_session_id uuid,
    CONSTRAINT ck_adaptive_repair_sessions_ck_adaptive_repair_sessions_13d0 CHECK ((attempted_count >= 0)),
    CONSTRAINT ck_adaptive_repair_sessions_ck_adaptive_repair_sessions_2ee3 CHECK (((current_difficulty >= (0)::double precision) AND (current_difficulty <= (1)::double precision))),
    CONSTRAINT ck_adaptive_repair_sessions_ck_adaptive_repair_sessions_458f CHECK (((target_exit_difficulty >= (0)::double precision) AND (target_exit_difficulty <= (1)::double precision))),
    CONSTRAINT ck_adaptive_repair_sessions_ck_adaptive_repair_sessions_55cc CHECK (((verification_average_score IS NULL) OR ((verification_average_score >= (0)::double precision) AND (verification_average_score <= (1)::double precision)))),
    CONSTRAINT ck_adaptive_repair_sessions_ck_adaptive_repair_sessions_5c4e CHECK (((initial_difficulty >= (0)::double precision) AND (initial_difficulty <= (1)::double precision))),
    CONSTRAINT ck_adaptive_repair_sessions_ck_adaptive_repair_sessions_6bcb CHECK ((max_questions > 0)),
    CONSTRAINT ck_adaptive_repair_sessions_ck_adaptive_repair_sessions_74e3 CHECK ((consecutive_correct >= 0)),
    CONSTRAINT ck_adaptive_repair_sessions_ck_adaptive_repair_sessions_a57f CHECK ((correct_count >= 0)),
    CONSTRAINT ck_adaptive_repair_sessions_ck_adaptive_repair_sessions_b0b1 CHECK ((correct_count <= attempted_count)),
    CONSTRAINT ck_adaptive_repair_sessions_ck_adaptive_repair_sessions_f6ed CHECK ((consecutive_wrong >= 0)),
    CONSTRAINT ck_adaptive_repair_sessions_ck_adaptive_repair_sessions_f77e CHECK (((((status)::text = 'ACTIVE'::text) AND ((outcome)::text = 'PENDING'::text) AND (completed_at IS NULL)) OR (((status)::text = 'COMPLETED'::text) AND ((outcome)::text <> 'PENDING'::text) AND (completed_at IS NOT NULL)))),
    CONSTRAINT ck_adaptive_repair_sessions_repair_cycle_index_positive CHECK ((repair_cycle_index >= 1))
);


ALTER TABLE public.adaptive_repair_sessions OWNER TO postgres;

--
-- Name: admission_data_sources; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.admission_data_sources (
    id uuid NOT NULL,
    name character varying(300) NOT NULL,
    source_type character varying(100) DEFAULT 'OFFICIAL_PORTAL'::character varying NOT NULL,
    source_url character varying(1000),
    publisher character varying(300),
    published_year integer NOT NULL,
    verified_at timestamp with time zone,
    verified_by uuid,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ck_admission_data_sources_name_not_blank CHECK ((length(TRIM(BOTH FROM name)) > 0)),
    CONSTRAINT ck_admission_data_sources_published_year_valid CHECK ((published_year >= 2000))
);


ALTER TABLE public.admission_data_sources OWNER TO postgres;

--
-- Name: admission_import_histories; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.admission_import_histories (
    id uuid NOT NULL,
    file_name character varying(255) NOT NULL,
    file_format character varying(11) NOT NULL,
    status character varying(9) DEFAULT 'PREVIEWED'::character varying NOT NULL,
    total_rows integer DEFAULT 0 NOT NULL,
    valid_rows integer DEFAULT 0 NOT NULL,
    imported_rows integer DEFAULT 0 NOT NULL,
    updated_rows integer DEFAULT 0 NOT NULL,
    skipped_rows integer DEFAULT 0 NOT NULL,
    error_rows integer DEFAULT 0 NOT NULL,
    errors json NOT NULL,
    preview_data json,
    target_year integer,
    data_source_id uuid,
